mapper.select:
SELECT ID, BATCH_NO, RULE_SET_ID, STATUS, SCANNED_COUNT, MATCHED_COUNT, EXPIRED_COUNT,
       ERROR_MESSAGE, STARTED_AT, FINISHED_AT
FROM PT_RULE_EVAL_BATCH WHERE BATCH_NO = #{batchNo}

mapper.update:
UPDATE PT_RULE_EVAL_BATCH SET SCANNED_COUNT = SCANNED_COUNT + #{scanned},
    MATCHED_COUNT = MATCHED_COUNT + #{matched}, EXPIRED_COUNT = EXPIRED_COUNT + #{expired}
WHERE BATCH_NO = #{batchNo}

UPDATE PT_RULE_EVAL_BATCH SET STATUS = 'RUNNING', SCANNED_COUNT = 0, MATCHED_COUNT = 0,
    EXPIRED_COUNT = 0, ERROR_MESSAGE = NULL, STARTED_AT = #{startedAt}, FINISHED_AT = NULL
WHERE BATCH_NO = #{batchNo}

mapper.select:
SELECT ID, PERSON_ID, TAG_ID, SOURCE_TYPE, RULE_SET_ID, RULE_VERSION, BATCH_NO, MATCH_DETAIL,
       EVIDENCE_STATUS, REVIEW_STATUS, REVIEWED_BY, REVIEWED_AT, CREATED_AT, UPDATED_AT
FROM PT_PERSON_TAG_EVIDENCE
WHERE PERSON_ID = #{personId} AND TAG_ID = #{tagId}
  AND RULE_SET_ID = #{ruleSetId} AND RULE_VERSION = #{ruleVersion}

mapper.update:
UPDATE PT_PERSON_TAG_EVIDENCE SET BATCH_NO = #{batchNo}, MATCH_DETAIL = #{matchDetail},
    EVIDENCE_STATUS = #{evidenceStatus}, REVIEW_STATUS = #{reviewStatus},
    REVIEWED_BY = #{reviewedBy}, REVIEWED_AT = #{reviewedAt}, UPDATED_AT = #{updatedAt}
WHERE ID = #{id}

UPDATE PT_PERSON_TAG_EVIDENCE SET EVIDENCE_STATUS = 'EXPIRED', UPDATED_AT = #{updatedAt}
WHERE PERSON_ID = #{personId} AND TAG_ID = #{tagId} AND RULE_SET_ID = #{ruleSetId}
  AND EVIDENCE_STATUS = 'ACTIVE'

UPDATE PT_PERSON_TAG_EVIDENCE SET REVIEW_STATUS = #{reviewStatus}, REVIEWED_BY = #{reviewedBy},
    REVIEWED_AT = #{reviewedAt}, UPDATED_AT = #{reviewedAt}
WHERE PERSON_ID = #{personId} AND TAG_ID = #{tagId} AND RULE_SET_ID = #{ruleSetId}
  AND EVIDENCE_STATUS = 'ACTIVE'

UPDATE PT_PERSON_TAG_EVIDENCE SET EVIDENCE_STATUS = 'EXPIRED', UPDATED_AT = #{updatedAt}
WHERE TAG_ID = #{tagId} AND SOURCE_TYPE = 'RULE' AND RULE_SET_ID <> #{activeRuleSetId}
  AND EVIDENCE_STATUS = 'ACTIVE'
